starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "secret_name" {
  description = "Input variable secret_name."
  type        = string
  default     = "app/credentials"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_secretsmanager_secret" "this" {
  # TODO - Complete the aws_secretsmanager_secret resource.
  # Add the arguments and nested blocks required for aws_secretsmanager_secret.
}

resource "aws_kms_key" "this" {
  description         = "Arena managed key"
  enable_key_rotation = true
}
